205	  private static <T extends @Nullable Object> boolean removeIfFromRandomAccessList(
206	      List<T> list, Predicate<? super T> predicate) {
207	    // Note: Not all random access lists support set(). Additionally, it's possible
208	    // for a list to reject setting an element, such as when the list does not permit
209	    // duplicate elements. For both of those cases,  we need to fall back to a slower
210	    // implementation.
211	    int from = 0;
212	    int to = 0;
213	
214	    for (; from < list.size(); from++) {
215	      T element = list.get(from);
216	      if (!predicate.apply(element)) {
217	        if (from > to) {
218	          try {
219	            list.set(to, element);
220	          } catch (UnsupportedOperationException e) {
221	            slowRemoveIfForRemainingElements(list, predicate, to, from);
222	            return true;
223	          } catch (IllegalArgumentException e) {
224	            slowRemoveIfForRemainingElements(list, predicate, to, from);
225	            return true;
226	          }
227	        }
228	        to++;
229	      }
230	    }
231	
232	    // Clear the tail of any remaining items
233	    list.subList(to, list.size()).clear();
234	    return from != to;
235	  }
