237	  private static <T extends @Nullable Object> void slowRemoveIfForRemainingElements(
238	      List<T> list, Predicate<? super T> predicate, int to, int from) {
239	    // Here we know that:
240	    // * (to < from) and that both are valid indices.
241	    // * Everything with (index < to) should be kept.
242	    // * Everything with (to <= index < from) should be removed.
243	    // * The element with (index == from) should be kept.
244	    // * Everything with (index > from) has not been checked yet.
245	
246	    // Check from the end of the list backwards (minimize expected cost of
247	    // moving elements when remove() is called). Stop before 'from' because
248	    // we already know that should be kept.
249	    for (int n = list.size() - 1; n > from; n--) {
250	      if (predicate.apply(list.get(n))) {
251	        list.remove(n);
252	      }
253	    }
254	    // And now remove everything in the range [to, from) (going backwards).
255	    for (int n = from - 1; n >= to; n--) {
256	      list.remove(n);
257	    }
258	  }
